<!doctype html>
<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tiket {{ $participant->ticket_number }}</title><style>:root{font-family:Inter,Arial,sans-serif;color:#152238;background:#edf4ff}*{box-sizing:border-box}body{margin:0}.wrap{max-width:540px;margin:auto;padding:26px 16px}.ticket{background:#fff;border:1px solid #d9e4f1;border-radius:22px;padding:26px;text-align:center;box-shadow:0 20px 45px #1c407026}.brand{color:#2165c5;font-weight:800;font-size:.76rem;letter-spacing:.08em}h1{font-size:1.2rem;margin:7px 0 17px;color:#263c60}.queue{background:#cfe2ff;border-radius:16px;padding:18px}.queue small{display:block;color:#4c70a8;font-size:.72rem}.number{font-size:clamp(3rem,14vw,5.6rem);font-weight:900;line-height:1;color:#124ea5;margin:6px 0 10px}.ref{font:.66rem ui-monospace,SFMono-Regular,monospace;color:#5576aa;word-break:break-all}.schedule{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:14px 0}.schedule div{background:#f8fafc;padding:10px;border-radius:10px;font-size:.77rem}.schedule span{display:block;color:#75839a;margin-bottom:4px}.schedule strong{font-size:.88rem}.qr{display:inline-flex;padding:13px;border:1px solid #dae5f4;border-radius:14px;margin:4px 0 12px}.name{font-weight:800;margin:3px 0}.hint{color:#71809a;font-size:.82rem;margin:4px 0}.status{display:inline-block;padding:6px 12px;border-radius:99px;background:#d9f7e2;color:#13733b;font-weight:700;font-size:.78rem;margin:6px 0 14px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:8px}.actions a{border:1px solid #bdcce0;border-radius:8px;padding:10px;color:#263c60;text-decoration:none;font-size:.83rem;font-weight:700}.lookup{display:block;margin-top:18px;font-size:.78rem;color:#3c6dae;text-decoration:none}@media print{body{background:#fff}.wrap{padding:0}.ticket{box-shadow:none;border:0}.actions,.lookup{display:none}}</style></head>
<body><main class="wrap"><section class="ticket"><div class="brand">SIOLA Q · TIKET EVENT</div><h1>{{ $event->name }}</h1><div class="queue"><small>Nomor antrean anda</small><div class="number">{{ $participant->ticket_number }}</div><div class="ref">{{ $participant->reference_code }}</div></div><div class="schedule"><div><span>Tanggal kedatangan</span><strong>{{ $event->arrival_date?->translatedFormat('l, d M Y') ?? $event->starts_at?->translatedFormat('l, d M Y') ?? 'Menunggu informasi' }}</strong></div><div><span>Sesi</span><strong>{{ $event->session_label ?: ($event->starts_at ? $event->starts_at->format('H:i').' WIB' : 'Menunggu informasi') }}</strong></div></div><div class="qr">{!! QrCode::size(172)->generate(route('event.ticket', ['token' => $event->public_token, 'ticket' => $participant->qr_token])) !!}</div><div class="name">{{ $participant->name }}</div><div class="hint">Tunjukkan QR ini saat check-in di lokasi</div><span class="status">{{ $participant->status === 'checked_in' ? 'Sudah check-in' : 'Terdaftar' }}</span><div class="actions"><a href="{{ route('event.ticket.download', ['token' => $event->public_token, 'ticket' => $participant->qr_token]) }}">⇩ Unduh tiket</a><a href="{{ route('event.ticket.calendar', ['token' => $event->public_token, 'ticket' => $participant->qr_token]) }}">▣ Ke kalender</a></div><a class="lookup" href="{{ route('event.lookup', $event->public_token) }}">Cek ulang pakai NIK / No. HP</a></section></main></body></html>
